from AlgorithmImports import *


class TwoStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.spy_cross_up = False
        self.spy_cross_down = False

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}
        self.last_evaluation_date = None

    def OnData(self, data):
        current_date = data.Time.date()

        self._update_spy_state(data, current_date)
        self._update_aapl_state(data, current_date)

        if self.last_evaluation_date == current_date:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.required_symbols):
            return

        self.last_evaluation_date = current_date

        self._evaluate_sells(data)
        self._evaluate_buys(data)

    def _update_spy_state(self, data, current_date):
        if not data.Bars.ContainsKey(self.spy):
            self.spy_cross_up = False
            self.spy_cross_down = False
            return

        bar = data.Bars[self.spy]
        close = float(bar.Close)

        self.spy_cross_up = False
        self.spy_cross_down = False

        if (
            self.spy_sma.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            current_sma = float(self.spy_sma.Current.Value)

            self.spy_cross_up = (
                self.previous_spy_close <= self.previous_spy_sma
                and close > current_sma
            )

            self.spy_cross_down = (
                self.previous_spy_close >= self.previous_spy_sma
                and close < current_sma
            )

        self.previous_spy_close = close

        if self.spy_sma.IsReady:
            self.previous_spy_sma = float(self.spy_sma.Current.Value)

    def _update_aapl_state(self, data, current_date):
        if not data.Bars.ContainsKey(self.aapl):
            return

        close = float(data.Bars[self.aapl].Close)

        if self.previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.previous_aapl_close = close

    def _evaluate_sells(self, data):
        if (
            self.strategy_a_lot > 0
            and self.spy_cross_down
            and self._strategy_has_no_pending_order("A")
        ):
            self._submit_order("A", self.spy, -self.strategy_a_lot, "sell")

        if (
            self.strategy_b_lot > 0
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60
            and self._strategy_has_no_pending_order("B")
        ):
            self._submit_order("B", self.aapl, -self.strategy_b_lot, "sell")

    def _evaluate_buys(self, data):
        if (
            self.strategy_a_lot == 0
            and self.spy_cross_up
            and self._strategy_has_no_pending_order("A")
        ):
            close = float(data.Bars[self.spy].Close)
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue)) // close
            )

            if quantity > 0:
                self._submit_order("A", self.spy, quantity, "buy")

        if (
            self.strategy_b_lot == 0
            and self.aapl_red_streak >= 3
            and self._strategy_has_no_pending_order("B")
        ):
            close = float(data.Bars[self.aapl].Close)
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= 20000:
                quantity = int(20000 // close)

                if quantity > 0:
                    self._submit_order("B", self.aapl, quantity, "buy")

    def _strategy_has_no_pending_order(self, strategy):
        return not any(
            item["strategy"] == strategy
            for item in self.pending_orders.values()
        )

    def _submit_order(self, strategy, symbol, quantity, side):
        ticket = self.MarketOrder(symbol, quantity)

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = {
                "strategy": strategy,
                "side": side
            }

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        order_info = self.pending_orders[order_id]
        fill_quantity = int(order_event.FillQuantity)

        if order_info["strategy"] == "A":
            self.strategy_a_lot += fill_quantity
            self.strategy_a_lot = max(0, self.strategy_a_lot)
        else:
            self.strategy_b_lot += fill_quantity
            self.strategy_b_lot = max(0, self.strategy_b_lot)

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            del self.pending_orders[order_id]
