        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {}

    def OnData(self, data: Slice):
        bars = data.Bars

        spy_bar = bars[self.spy] if bars.ContainsKey(self.spy) else None
        aapl_bar = bars[self.aapl] if bars.ContainsKey(self.aapl) else None

        current_spy_close = None
        current_spy_sma = None
        if spy_bar is not None:
            current_spy_close = float(spy_bar.Close)
            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if current_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if spy_bar is not None and current_spy_sma is not None:
            spy_cross_up = (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and current_spy_close > current_spy_sma
            )

            spy_cross_down = (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and current_spy_close < current_spy_sma
            )
        else:
            spy_cross_up = False
            spy_cross_down = False

        if self.IsWarmingUp:
            self._update_previous_state(
                current_spy_close,
                current_spy_sma,
                aapl_bar
            )
            return

        if not all(bars.ContainsKey(symbol) for symbol in self.symbols):
            self._update_previous_state(
                current_spy_close,
                current_spy_sma,
                aapl_bar
            )
            return

        aapl_rsi_ready = self.aapl_rsi.IsReady
        aapl_rsi_above_60 = (
            aapl_rsi_ready and float(self.aapl_rsi.Current.Value) > 60
        )

        if (
            self.strategy_a_lot > 0
            and not self._has_pending_order("A")
            and spy_cross_down
        ):
            self._submit_order("A", self.spy, -self.strategy_a_lot)

        if (
            self.strategy_b_lot > 0
            and not self._has_pending_order("B")
            and aapl_rsi_above_60
        ):
            self._submit_order("B", self.aapl, -self.strategy_b_lot)

        if (
            self.strategy_a_lot == 0
            and not self._has_pending_order("A")
            and spy_cross_up
        ):
            quantity = int(
                math.floor(
                    (0.40 * float(self.Portfolio.TotalPortfolioValue))
                    / current_spy_close
                )
            )
            if quantity > 0:
                self._submit_order("A", self.spy, quantity)

        if (
            self.strategy_b_lot == 0
            and not self._has_pending_order("B")
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20000
        ):
            quantity = int(math.floor(20000 / current_aapl_close))
            if quantity > 0:
                self._submit_order("B", self.aapl, quantity)

        self._update_previous_state(
            current_spy_close,
            current_spy_sma,
            aapl_bar
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if strategy == "A":
            self.strategy_a_lot = max(
                0,
                self.strategy_a_lot + fill_quantity
            )
        elif strategy == "B":
            self.strategy_b_lot = max(
                0,
                self.strategy_b_lot + fill_quantity
            )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_event.OrderId]

    def _submit_order(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=strategy)
        if ticket is not None:
            self.pending_orders[ticket.OrderId] = strategy

    def _has_pending_order(self, strategy):
        return strategy in self.pending_orders.values()

    def _update_previous_state(self, spy_close, spy_sma, aapl_bar):
        if spy_close is not None:
            self.previous_spy_close = spy_close

        if spy_sma is not None:
            self.previous_spy_sma = spy_sma

        if aapl_bar is not None:
